import React from 'react';

const Header = () => {
  return (
    <div className="header">
      <input type="text" className="search-bar" placeholder="Search..." />
      <div className="header-right">
        <span>Monday, 6th March</span>
      </div>
    </div>
  );
};

export default Header;
